(async()=>{let data=window.CHIHOME_EDITOR_CONFIG||await(await fetch('content.json')).json();const host=document.getElementById('fields'),status=document.getElementById('editor-status');const labels={welcomePopup:'Popup chào mừng — ảnh bìa và CTA',hero:'Hero — ảnh, video, nội dung',apartments:'Căn hộ — thêm, sửa, xóa',videos:'Room tour — video và thumbnail',tokens:'Màu sắc thương hiệu',sections:'Section — thứ tự và ẩn/hiện',copy:'Toàn bộ nội dung giao diện VI/EN',contact:'Liên hệ và mạng xã hội',backend:'Kết nối backend',analytics:'Analytics',about:'Về ChiHome — giới thiệu doanh nghiệp',reviews:'Đánh giá đã xác minh',articles:'Bài viết liên quan',sources:'Nguồn tài nguyên'};const templates={units:{id:'new-unit',name:'',code:'',parentCollection:'',sourceTitle:'',sourceAlbum:'',area:null,bedrooms:null,bathrooms:null,guests:null,image:'',gallery:[],galleryCaptions:{vi:[],en:[]},location:'Thủ Thiêm · Ho Chi Minh City',price:'',features:{vi:[],en:[]},article:{vi:{title:'',intro:'',paragraphs:[]},en:{title:'',intro:'',paragraphs:[]}},reviews:[]},reviewExamples:{author:'',avatar:'',illustrative:true,text:{en:'',vi:''}},apartments:{id:'new-apartment',name:'New apartment',image:'assets/opera.jpg',gallery:['assets/opera.jpg'],location:'Thủ Thiêm',bedrooms:null,guests:null,demo:true,en:'Description',vi:'Mô tả',amenities:{en:[],vi:[]},price:'',source:'https://chihome.vn/'},videos:{title:{en:'Room tour',vi:'Room tour'},thumbnail:'assets/hero.jpg',url:'',aspect:'9:16'},sections:{id:'apartments',visible:true},reviews:{author:'',text:{en:'',vi:''},source:'',permission:false},faq:{en:'Question',vi:'Câu hỏi',answer:{en:'Answer',vi:'Trả lời'}},articles:{title:{en:'Title',vi:'Tiêu đề'},subtitle:{en:'Description',vi:'Mô tả'},url:''}};
function el(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e}function save(){const output=document.getElementById('chihome-json');if(output)output.value=JSON.stringify(data);status.textContent='Thay đổi chưa được lưu. '+(output?'Nhấn Lưu thay đổi ở cuối trang.':'Xuất content.json để lưu.');}function field(parent,key,value,path){if(value!==null&&typeof value==='object'){const group=el('details');group.className='editor-group';group.append(el('summary',labels[key]||key));if(Array.isArray(value)){value.forEach((item,i)=>{const box=el('div');box.className='array-item';const actions=el('div');actions.className='item-actions';actions.append(el('strong',`${i+1}. ${item?.name||item?.id||item?.en||key}`));[['↑',()=>{if(i>0)[value[i-1],value[i]]=[value[i],value[i-1]]}],['↓',()=>{if(i<value.length-1)[value[i+1],value[i]]=[value[i],value[i+1]]}],['Xóa',()=>value.splice(i,1)]].forEach(([text,fn])=>{const b=el('button',text);b.type='button';b.onclick=()=>{fn();render();save()};actions.append(b)});box.append(actions);field(box,i,item,[...path,i]);group.append(box)});const add=el('button','+ Thêm');add.type='button';add.onclick=()=>{value.push(structuredClone(templates[key]??(value[0]??'')));render();save()};group.append(add)}else Object.entries(value).forEach(([k,v])=>field(group,k,v,[...path,k]));parent.append(group);return;}const row=el('label');row.className='editor-field';const label=el('span',String(key));label.append(el('div',path.join(' › ')));label.lastChild.className='field-path';row.append(label);const input=el(typeof value==='string'&&(value.length>100||['title','subtitle','en','vi'].includes(String(key)))?'textarea':'input');if(input.tagName==='INPUT')input.type=typeof value==='boolean'?'checkbox':typeof value==='number'||value===null?'number':'text';if(typeof value==='boolean')input.checked=value;else input.value=value??'';input.oninput=()=>{const keys=path;let ref=data;keys.slice(0,-1).forEach(k=>ref=ref[k]);ref[keys.at(-1)]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''?null:Number(input.value)):input.value;save()};row.append(input);parent.append(row)}function render(){host.innerHTML='';Object.entries(data).forEach(([k,v])=>field(host,k,v,[k]));}
render();document.getElementById('export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=el('a');a.href=URL.createObjectURL(blob);a.download='content.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status.textContent='Đã xuất nội dung.'};document.getElementById('import').onchange=async e=>{try{const next=JSON.parse(await e.target.files[0].text());if(!next.hero||!Array.isArray(next.apartments)||!Array.isArray(next.sections))throw Error();data=next;render();save()}catch{status.textContent='JSON không hợp lệ hoặc thiếu cấu trúc ChiHome.'}};const preview=document.getElementById('editor-preview');function updatePreview(){const previewData=structuredClone(data);previewData.backend={endpoint:'',nonce:''};previewData.analytics={enabled:false,gtmId:''};preview.contentWindow.postMessage({type:'chihome-preview',config:previewData},location.origin)}preview.addEventListener('load',updatePreview);document.getElementById('preview').onclick=()=>{updatePreview();status.textContent='Đã cập nhật preview. Chưa lưu lên máy chủ.'};save();status.textContent='Sẵn sàng biên tập.';
})();
